  import FulltextSettingsApiService from 'src/services/settings/FulltextSettingsApiService';
  import { parseDashboardQueryParams } from 'src/pages/Dashboard/dashboardQueryParams';
  import ColumnOrderBy from 'src/pages/Dashboard/column-orderBy.vue';
  import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
  import { date, LocalStorage, SessionStorage, debounce } from 'quasar';
  import { getStatusValue } from 'src/pages/PurchaseOrders/constants.js';
  import { getOrgId, addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
  import PaginationSettings from 'src/pages/Dashboard/advancedSettings/pagination-settings.vue';
  import { genericService, documentListApiService, documentDetailApiService } from 'src/services';
  import SupplierApprovalStatus from 'src/components/SupplierApprovalStatus/SupplierApprovalStatus.vue'
  import dragDropColumn from 'src/mixins/dragDropColumn';
  import {
    useUserStore,
    useSettingStore,
    useDashboardStore,
    useWebSocketStore,
    useDocAttributesStore} from 'src/store/main';
  import {
    CONSTANTS,
    isInvoice,
    dashboard_v2,
    readOnlyDocStatus,
    dashboarDateColumns,
    approve_before_export_v2,
    validationScreenStatuses,
    filters_reset_after_restart_setting,
  } from 'src/constants';

  export default defineComponent({
    el: '#app',
    mixins: [
      cache, dateUtils,
      helperUtil,
      helperMixin,
      docTypeLable,
      documentUtil,
      poActionsUtil,
      displayFieldLabel,
      dragDropColumn
    ],
    components: {
      draggable: VueDraggableNext,
      SupplierApprovalStatus,
      PaginationSettings,
      DashboardHeader,
      DocAssignment,
      ColumnOrderBy,
      MobileGrid,
      TableBody,
      SubHeader,
      Loader,
      
    },
    
    data() {
      return {
        all_invoice_data: [], // all data, will filter records from this
        InvoicesClearInterval: 0 as any,
        po_module_activate: false as boolean | undefined,
        debounceSearchInputFunc: {} as any,
        confirmMergeDialog: false,
        filters_reset_after_restart_setting,
        groupedColumns: ref([] as any),
        isGroupingMode: ref(false),
        group_key: ref(CONSTANTS.group_key),
        availableGroupingColumns: ref([] as any),
        date_fields: [
            'created_on',
            'last_modified_on',
            'invoice_date',
            'delivery_date',
            'order_date'
        ],
      };
    },
    beforeRouteLeave: function (to: any, from: any, next: any) {
      // Before leaving this page, lets first reset everything
      this.intervalManager(false);
      this.unsubscribeToChannel('dashboard');
      this.unsubscribeToChannel('pending_docs');
      next();
    },

    async mounted() {
      try {

        // Settings are already loaded during PrepareDashboard
        // Just initialize the settings UI without re-fetching
        this.initSettings();
        // await this.getProfile();
        this.getUserDetailByKey();
        this.processing = true;
        // this.fetchInvoices(true, true);
        await this.getSavedColumns(); //not blocking due settings already fetched
        this.table_columns = await this.handleTableColumns(false);
        this.prepareStatusList();
        await this.getOrderBy(); //not blocking due settings already fetched
        // await this.getPaginationSize(); //not blocking due settings already fetched

        this.po_module_activate = true;
        this.getSavedFilters();
        // await this.applySavedFilters();
        this.initGroups();
        await this.loadData();
        this.clearSelectedSessionStorage();
        // Updating data every 1 minute
        this.intervalManager(true);
        this.subscribeToDashboardChannel();
        this.getDocTypeAllSettings();

        if (this.$route.params.force_restart && this.$route.params.force_restart === 'force_restart') {
          this.restartExportedInvoices = true;
        }
        this.headerCheckbox = false;

        document.addEventListener('reset_pages', this.resetPages);
        document.addEventListener('reset_filters', this.resetFilters);
        document.addEventListener('on_row_click', this.rowClickEvent);
        document.addEventListener('apply_filters', this.applyFilterEvent);
        document.addEventListener('assignment_success', this.assignmentSuccess);
        document.addEventListener('dashboard_refresh_data', this.refreshFilters);

        this.initailizeDragColumnsById('dashboard')
        //listen for the column drop event
        document.addEventListener('dashboard-column-drop',(event: any) => {
          this.saveSortedColumns(event.detail)
        })
        this.debounceSearchInputFunc = debounce(() => {
          this.applyFilter();
        }, 1000);
      } catch (err) {
        logError(err);
      } finally {
        this.processing = false;
      }
      
      (<any>window).dash = this;
    },
    unmounted: function () {
      document.removeEventListener('keydown', this.keyDownEvent);
      document.removeEventListener('reset_filters', this.resetFilters);
      document.removeEventListener('apply_filters', this.applyFilterEvent);
      document.removeEventListener('assignment_success', this.assignmentSuccess);
      document.removeEventListener('dashboard_refresh_data', this.refreshFilters);
      document.removeEventListener('dashboard-column-drop',(event: any) => {
          this.saveSortedColumns(event.detail)
        })
    },

    watch: {
      headerCheckbox() {
        if (this.headerCheckbox === false) {
          this.headerFabIcon = false;
          this.isMultiDeleteButtonDisabled = false;
          this.isMultiRestartButtonDisabled = false;
          // this.intervalManager(true);
        } else {
          // this.intervalManager(false);
        }
      },
      processing: {
        handler: function (newVal, oldVal) {
          if (newVal == true) {
            this.showLoading();
          } else {
            this.hideLoading();
          }
        },
      },
      isConnected: {
        handler: function (newVal, oldVal) {
          this.use_websocket = true;
          this.subscribeToDashboardChannel();
        },
      },
      websocketHasError: {
        handler: function (newVal, oldVal) {
          if (newVal == true) {
            this.use_websocket = false;
            this.handleWebsocketDelay();
          }

        },
      },
      dashboard_data_flag: {
        handler: function (newVal, oldVal) {
          if (newVal == false) {
            return;
          }

          this.data_status = 'received';
          this.handleWebSocketResult(this.dashboard_data);
        },
      },
    },
    methods: {
      getUserDetailByKey() {
        let organisationsFromStorage = getUserDetailFromkey('organisations');
        let FirstIndexOfOrganisations = organisationsFromStorage[0] as any;
        if(!FirstIndexOfOrganisations) {
          return;
        }
        if(FirstIndexOfOrganisations.status === 'pending_ap_approval'){
          this.supplier_approval_status = 'pending_approval';
        }else{
          this.supplier_approval_status = FirstIndexOfOrganisations.status
        }
        this.supplier_lookup_record_id = FirstIndexOfOrganisations.supplier_lookup_record_id ? FirstIndexOfOrganisations.supplier_lookup_record_id : 'supplier_lookup_record_id'
        this.supplier_as_org_id = FirstIndexOfOrganisations.supplier_as_org_id ? FirstIndexOfOrganisations.supplier_as_org_id : 'supplier_as_org_id'
      },
      initSettings() {
        if(this.user_settings[dashboard_v2]) {
          this.isGroupingMode = true;
        }
      },
      initGroups() {
        this.group_key = getUserBasedKey(this.group_key);
        const groupByData = LocalStorage.getItem(this.group_key) as string;
        if(groupByData) {
            this.groupedColumns = JSON.parse(groupByData);
        }
      },
      applyFilterEvent(e: any) {
        if (e && e.detail && e.detail.reset_pagination === true) {
          this.resetPagination = true;
        }
        this.applyFilter();
      },
      dashboardColumnsEvent() {
        this.dashboardColumnsUpdated();
      },

      async dashboardColumnsUpdated() {
        this.table_columns = await this.handleTableColumns();
        await this.applySavedFilters();
        this.fetchInvoices(true);
      },

      intervalManager(intervalFlag: boolean) {
        clearInterval(this.InvoicesClearInterval);
        if (intervalFlag === true) {
          // TODO revert it lator on and handle it accordingly
          // this.InvoicesClearInterval = setInterval(() => {
          //   if (this.is_any_checked) {
          //     // dont refresh if user is in the middle of something
          //     return;
          //   }
          //   this.fetchInvoices(false);
          // }, 60000);
        }
      },

      async applySavedFilters() {
        this.pageSize = Number(this.pagination_size);
        this.queryParams = '?&skip=' + this.startfrom + '&limit=' + this.pageSize;
        this.queryParams += await this.makeQueryParamFromFilters(false);
        // this.paginationCount = this.startfrom / this.pageSize + 1;
        this.resetPagination = false;
      },

      handleActions(id: any) {
        this.display_data.forEach((row: any, index: any) => {
          if (index !== id) {
            row['fabAction'] = false;
          }
        });
        return true;
      },

