      },
      resetPages() {
        this.resetPagination = true;
      },
      async applyFilter() {
        this.processing = true;
        this.resetAllSelectedRows();

        if (this.resetPagination == true) {
          this.startfrom = 0;
          this.paginationCount = 1;
        }
        this.resetPagination = true;

        this.queryParams += await this.makeQueryParamFromFilters();
        if (this.queryParams == '') {
          this.removeSavedFilters();
        }

        this.queryParams = '?&skip=' + this.startfrom + '&limit=' + this.pageSize;
        this.fetchInvoices(true);
      },

      async refreshFilters(e:any) {
        let show_shimmer_loader = false;
        let refresh_cache = false;

        if (e && e.detail && e.detail.show_shimmer_loader) {
          show_shimmer_loader = true;
        }
        if (e && e.detail && e.detail.refresh_cache) {
          refresh_cache = true;
        }

        this.all_invoice_data = [];
        this.display_data = [];
        this.selectionList = [];
        this.headerCheckbox = false;

        // Bug-2026-04-24 (Cache-Clear-Fix): User-triggered "Refresh
        // Table" must drop the fulltextsearch `search_results:*` Redis
        // cache BEFORE we re-fetch — otherwise the next
        // `/document/dashboards` read returns the same cached doc_id
        // list for up to 3 min (`SEARCH_RESULTS_CACHE_TTL`), even
        // though the user explicitly asked for fresh data. The
        // previous implementation fired the invalidate request in
        // dashboard.vue's handler as fire-and-forget, racing the
        // parallel fetchInvoices() from THIS handler — the fetch
        // often arrived before the cache-clear finished.
        //
        // AWAIT here guarantees the cache is gone before our fetch
        // hits the API. If the invalidate fails we still fall through
        // to fetchInvoices: the 3-min TTL is the backstop and the
        // user sees correct data within that window regardless.
        if (refresh_cache) {
          try {
            const api = new FulltextSettingsApiService();
            await api.invalidateSearchCache();
          } catch (_err) {
            // Non-blocking — TTL backstop bounds the stale-window
            // at 3 min even when invalidation fails.
          }
        }

        this.fetchInvoices(true, show_shimmer_loader, refresh_cache);
      },

      async fetchInvoices(showLoader: boolean, show_shimmer_loader = true, refresh_cache = false) {
        await this.applySavedFilters();

        if(this.isGroupingMode) {
          if (showLoader) {
            this.processing = true;
          }
          await this.fetchInvoicesWithGrouping(showLoader, show_shimmer_loader, refresh_cache);
          this.processing = false;
          return;
        }

        await this.fetchInvoicesWithoutGrouping(showLoader, show_shimmer_loader, refresh_cache);
      },
      async fetchInvoicesWithGrouping(showLoader: boolean, show_shimmer_loader = true, refresh_cache = false) {
        try {
          
          
          const parentIndexes = LocalStorage.getItem(CONSTANTS.group_parent_indexes) as string;
          const groupParentRawWhere = LocalStorage.getItem(CONSTANTS.group_parent_raw_where) as string;
          
          if(parentIndexes && groupParentRawWhere) {
            await this.fetchOpendGroupsData(parentIndexes, groupParentRawWhere);
            LocalStorage.remove(CONSTANTS.group_parent_indexes);
            LocalStorage.remove(CONSTANTS.group_parent_raw_where);
            return;
          }
          
          let response = await this.fetchGroupData([]);
          
          if (response.success === false) {
            throw response;
          }
          
          this.updateDocumentStats(response);
          this.updateTableData(response);
        } catch (err) {
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(msg);
          logError(err);
        }
      },
      async fetchOpendGroupsData(parentIndexes: string, groupParentRawWhere: string) {
        try {

          let queryParamsList = await this.prepareGroupingQueryParams(JSON.parse(groupParentRawWhere));

          let response = await documentListApiService.fetchOpendGroupsData(queryParamsList);
          this.prepareOpenGroupData(response, parentIndexes);

        } catch (err: any) {
          // Bug-31 (2026-04-24): 422/400 = invalid raw_query. Chip
          // editor's inline banner already shows exactly what's wrong;
          // toast would be duplicate noise. Helper covers HTTP + WS.
          if (!isQueryValidationError(err)) {
            const apiMsg = ApiExceptions.getErrorMessage(err as dynamicObj);
            notify.error(this.$t('ERROR_FETCHING_INVOICES'), { detail: apiMsg.detail, fullDetail: apiMsg.fullDetail });
          }
          logError(err.message);
        }
      },
      async prepareGroupingQueryParams(groupParentRawWhere: any) {
        let queryParamsList = [] as any;

        let groupItem = this.getGroupBy(0);

        if (objLen(groupItem) !== 0) {
          const groups = []
          const group_item = {} as dynamicObj;
          group_item[groupItem.name] = groupItem.hasOwnProperty('group_by_type') ? groupItem.group_by_type : '';
          groups.push(group_item);
          this.queryParams += '&group_by=' + JSON.stringify(groups);
        }
        queryParamsList.push(this.queryParams);

        let grouping_where = [] as any;

        for(let where of groupParentRawWhere) {

          grouping_where.push(where);

          await this.applySavedFilters();

          if (grouping_where.length > 0) {
            this.queryParams += '&raw_where=' + JSON.stringify(grouping_where);
          }

          let groupItem = this.getGroupBy(grouping_where.length);
          
          if (objLen(groupItem) !== 0) {
            const groups = []
            const group_item = {} as dynamicObj;
            group_item[groupItem.name] = groupItem.hasOwnProperty('group_by_type') ? groupItem.group_by_type : '';
            groups.push(group_item);
            this.queryParams += '&group_by=' + JSON.stringify(groups);
          }

          queryParamsList.push(this.queryParams);
        }
         
        return queryParamsList;
      },
      prepareOpenGroupData(response: any, parentIndexes: string) {
        
        this.updateTableData(response[0].data);
        response.shift();
        
        let indexCounter = 0;
        let myParentsList = [] as any;
        const parentIndexesList = parentIndexes.split(',');

        for(let item of response) {
          const data = this.prepareGroupingData(
            item.data.documents,
            this.getGroupBy(indexCounter + 1)?.name,
          );
          this.applyCustomFormatOnRows(data);

          myParentsList.push(parentIndexesList[indexCounter]);
          indexCounter++;

          // here prepare parentIndexes
          const parentRows = this.getParentRows(myParentsList);
          parentRows[parentRows.length - 1]['_children'] = data;
        }
        this.markGroupAsOpend(myParentsList, this.display_data);
        
      },
      // make a recursion to open the child rows
      markGroupAsOpend(myParentsList: any, tableData: any) {
        
        if(!myParentsList || myParentsList.length == 0) {
          return;
        }

        const index = Number(myParentsList[0]);
        myParentsList.shift();
        
        const rowData = tableData[index];
        // mark group as opend
        rowData.is_expend = true;

        this.markGroupAsOpend(myParentsList, rowData._children);
      },
      async fetchInvoicesWithoutGrouping(showLoader: boolean, show_shimmer_loader = true, refresh_cache = false) {

        try {
          if (showLoader) {
            this.processing = true;
          }

          if (show_shimmer_loader) {
            this.display_data = [];
            this.selectionList = [];
            this.headerCheckbox = false;
            this.show_table_loader = true;
          }
          // this.queryParams += '&refresh_dashboard_cache=' + refresh_cache;

        //   socket for grouping is not available
          if (this.use_websocket) {
            // add wait for 5 second if there is till no response then switch to https
            this.terminateLongRunningTask(this.getWebSocketDashboard(), 5000).catch(() => {
              // Timeout handled internally by handleWebsocketDelay()
            });

            return;
          } else {

            let response = await documentListApiService.getList(this.queryParams);
            this.updateDocumentStats(response);
            this.updateTableData(response);
            this.processing = false;
            setTimeout(this.turnOnWebSocket, 5000);
          }
        } catch (err: any) {
          // Bug-31 (2026-04-24): 422/400 = invalid raw_query. Chip
          // editor's inline banner already shows exactly what's wrong;
          // toast would be duplicate noise. Helper covers HTTP + WS.
          if (!isQueryValidationError(err)) {
            const apiMsg = ApiExceptions.getErrorMessage(err as dynamicObj);
            notify.error(this.$t('ERROR_FETCHING_INVOICES'), { detail: apiMsg.detail, fullDetail: apiMsg.fullDetail });
          }
          logError(err.message);
          this.processing = false;
          // Bug-2026-04-24: clear the shimmer skeleton on error too.
          // Without this the table sat in loading-rows state forever
          // when raw_query 422'd, even though `processing` was false —
          // skeleton was tied to a separate flag that nothing reset.
          // User-visible symptom: "läuft ewig" search after typing
          // anything the parser doesn't accept.
          this.show_table_loader = false;
        }
      },

      handleWebsocketDelay () {
        // websocket is still fetching data and we are not getting any response
        if (this.data_status === 'received') {
          return;
        }
        this.use_websocket = false;
        this.fetchInvoices(false);
        this.processing = false;
        setTimeout(this.turnOnWebSocket, 5000);
      },

      turnOnWebSocket () {
        if (this.websocketHasError) {
          return;
        }

        this.use_websocket = true;
      },

      terminateLongRunningTask(promise: any, ms: number) {
          return new Promise((resolve, reject) => {
              const timer = setTimeout(() => {
                  reject(new Error('Operation timed out'));
                  this.handleWebsocketDelay();
              }, ms);

              promise.then((result: any) => {
                      clearTimeout(timer);
                      resolve(result);
                  })
                  .catch((err: any) => {
                      clearTimeout(timer);
                      reject(err);
                      this.handleWebsocketDelay();
                  });
          });
      },

      updateTableData(response: dynamicObj) {
        this.resultsCount = response.overview['results-count'] as number;
        this.current_invoice_count = this.resultsCount;
        let temp = this.resultsCount / this.pageSize;
        this.skip = Math.ceil(temp);

        let data: any = [];
        if (response.documents) {
          data = response.documents;
        }

        if(this.groupedColumns && this.groupedColumns.length > 0) {
          data = this.prepareGroupingData(data, this.getGroupBy(0)?.name);
        }
        this.availableGroupingColumns = response.available_grouping_columns;

        this.display_data = data;
        this.applyCustomFormatOnRows(this.display_data);

        this.show_table_loader = false;
        this.processing = false;
      },
      prepareGroupingData(data: any, groupColumnName?: string | null): any {
        // check if row toggler is open then need to add deta specificaly in that row
        // check if grouped data add the toggler
        if(
          data &&
          data.length > 0 &&
          (
            (
              groupColumnName &&
              Object.prototype.hasOwnProperty.call(data[0], groupColumnName)
            ) ||
            Object.prototype.hasOwnProperty.call(data[0], 'count')
          )
        ) {

          const columnName = groupColumnName || this.getFirstItemColumnName(JSON.parse(JSON.stringify(data[0])));
          for(let index = 0; index < data.length; index++) {
            const tableRow = data[index];
            tableRow.column_name = columnName;
            tableRow.is_expend = false;
            tableRow._is_group_row = true;
            tableRow.id = tableRow.id || `${columnName}:${String(tableRow[columnName] ?? '')}:${index}`;
            tableRow.count = this.getGroupRowCount(tableRow);
            if(columnName == 'status') {
              tableRow['label'] = this.getLabelTranslation(tableRow[columnName]);

            } else if(columnName == 'doc_type') {
              tableRow['label'] = this.displayDocType(tableRow[columnName]);
            
            } else if(dashboarDateColumns.includes(columnName)) {
              tableRow['label'] = this.formatDateAccordingToPreference(tableRow[columnName], true);
            } else {
              tableRow['label'] = tableRow[columnName];
            }
          }
        }

        return data;
      },
      getFirstItemColumnName(firstItem: any) {
        delete firstItem.count;
        delete firstItem.documents;
        delete firstItem.document_count;
        delete firstItem.documents_count;
        delete firstItem.id;

        return Object.keys(firstItem)[0];
      },
      getGroupRowCount(row: any) {
        return row.count ??
          row.documents ??
          row.document_count ??
          row.documents_count ??
          0;
      },
      getDocTypeLabel(row: any) {
        const type = this.getDocTypeForDisplay(row);
        const label = this.displayDocType(type);
        return String(label);
      },
      updateDocumentStats(response: dynamicObj) {
        this.all_invoices = response.overview['all-invoices'] as number;
        this.automatically_processed = response.overview['automatically-processed'] as number;
        this.manually_processed = response.overview['manually-processed'] as number;
        this.completed = response.overview['completed'] as number;
        this.in_progress = response.overview['processing'] as number;
        this.pending = response.overview['pending-user-input'] as number;
        this.validated_pending_approval = response.overview['validated-pending-approval'] as number;
        this.approved_pending_second_approval = response.overview['approved-pending-second-approval'] as number;
        this.error = response.overview['error'] as number;
      },
      applyCustomFormatOnRows(display_data: any) {

        display_data.forEach((row: dynamicObj) => {
          row['fabAction'] = false;
          row['rowSelection'] = false;

          // row['created_on'] = row['created_on']
          //   ? this.formateDate(row['created_on']) + ' ' + this.formatTime(row['created_on'])
          //   : '-';
          // row['last_modified_on'] = row['last_modified_on']
          //   ? this.formateDate(row['last_modified_on']) + ' ' + this.formatTime(row['last_modified_on'])
          //   : '-';

            if (row.hasOwnProperty('po_match_status')
             && !isUndefinedOrNull(row['po_match_status'])
