          return;
        }
        let img = '';
        if (export_log.export_application == 'FLOW2') {
          img = 'images/flow2_icon.svg';
        }
        if (export_log.export_application == 'IDM') {
          img = 'images/idm_icon.svg';
        }
        if (export_log.export_application == 'ZUGFERD') {
          img = 'images/zugferd-icon.svg';
