      selectAllItems(data: any) {

        for(let row of data) {

          if(row.hasOwnProperty('_children') && row._children.length > 0 ) {
            // make a recurson
            this.selectAllItems(row._children);
            continue;
          }

          if(!row.hasOwnProperty('rowSelection')) {
            continue;
          }

          row['rowSelection'] = true;
          const existRow = this.selectionList.find((id: any) => id === row.id);
          if (!existRow) {
            this.selectionList.push(row.id);
          }
          if (this.isMultiDeleteButtonDisabled === false) {
            this.isMultiDeleteButtonDisabled = !this.isDocDeleteable(row);
          }
  
          if (this.isMultiRestartButtonDisabled === false) {
            this.isMultiRestartButtonDisabled = !this.isDocRestartable(row);
          }
        }
