          }

          if (this.isMultiRestartButtonDisabled === false) {
            this.isMultiRestartButtonDisabled = !this.isDocRestartable(row);
          }

        } else {
          const indexToRemove = this.selectionList.indexOf(row.id);
          if (indexToRemove !== -1) {
            this.selectionList.splice(indexToRemove, 1);
          }

          this.selectionList.forEach((row_id: string) => {

            const row = this.findItemById(row_id, this.display_data);

            if (this.isMultiDeleteButtonDisabled === false) {
              this.isMultiDeleteButtonDisabled = !this.isDocDeleteable(row);
            }
    
            if (this.isMultiRestartButtonDisabled === false) {
              this.isMultiRestartButtonDisabled = !this.isDocRestartable(row);
            }
          });
        }

        // if (this.display_data.length === this.selectionList.length) {
        //   this.headerCheckbox = true;
