      subscribeToDashboardChannel() {
        if (this.$route.path !== '/dashboard') {
          return;
        }
        // ✅ FIX: Enable WebSocket subscription to receive dashboard document data
        this.subscribeToChannel('dashboard');
        this.prewarmDashboardCache();
      },

      /**
       * Fire-and-forget pre-warm request. The first dashboard request
       * after a fresh WebSocket connect pays a ~1.5–2s cold-cache cost
       * on the backend (org_preferences + column_config + overview
       * aggregation). Sending a no-op `dashboard` message with a tiny
       * limit fills those Redis caches before the user's real query
       * arrives, so the first actual search lands on the warm path.
       *
       * Deliberately ignores the response and any errors — this is a
       * best-effort optimisation, never a gate on the UI.
       */
      prewarmDashboardCache() {
        if ((this as any).__dashboardPrewarmed) {
          return;
        }
        (this as any).__dashboardPrewarmed = true;
        try {
          this.sendMessageToSocket('dashboard', {
            skip: '0',
            limit: '1',
          }).catch(() => {
            // Intentional: pre-warm failures are silent.
          });
        } catch {
          // Swallow — pre-warm never fails the UI.
        }
      },

