      handleDragStart(event: any, columnInfo: any, columnIndex: number, table_columns: any) {
        event.dataTransfer.setData('application/json', JSON.stringify({columnIndex: columnIndex, columnInfo :columnInfo}));
        this.onDragStart(event, table_columns, columnIndex);
      },
      handleDragOver(event: any) {
        // This allows the drop operation to happen
        event.preventDefault();
      },
      handleColumSortEvent(event: any, columnIndex: number) {
          // Prevent default behavior
          event.preventDefault();

          // Retrieve the data from the drag operation
          const data = event.dataTransfer.getData('application/json');
          if(!data) {
              return;
          }
          const droppedData = JSON.parse(data);

          // if dropped on same element do noting
          if(columnIndex == droppedData.columnIndex) {
              return;
          }

          let columnToMove =  this.table_columns[droppedData.columnIndex];
          //remove the old item from old index
          this.table_columns.splice(droppedData.columnIndex, 1);

          // update Table row object
          this.table_columns.splice(columnIndex, 0, columnToMove);
      },
      headerGroupDropEvent(e: any) {

        e.preventDefault();
        this.onDragLeave();
        // e.currentTarget.classList.remove('opacity-half');
        const data = e.dataTransfer.getData('application/json');
        if(!data) {
            return;
        }

        const droppedData = JSON.parse(data);

        if(this.availableGroupingColumns && !this.availableGroupingColumns.includes(droppedData.columnInfo.name)) {
          notify.error('Grouping not allowed on this column');
          return;
        }

        // means group is already added
        if (this.groupedColumns.some((group: any) => group.name === droppedData.columnInfo.name)) {
            return;
        }

        if (this.date_fields.includes(droppedData.columnInfo.name) && !droppedData.columnInfo['group_by_type']) {
            droppedData.columnInfo['group_by_type'] = 'month';
        }

        // add column to group
        this.groupedColumns.push(droppedData.columnInfo);

        // cache the groupedColumns
        this.setGroupsToCache();

        this.resetAndFetchAgain();
      },
      setGroupsToCache() {
        if(this.groupedColumns && this.groupedColumns.length > 0) {
          LocalStorage.set(this.group_key, JSON.stringify(this.groupedColumns));
        } else {
          LocalStorage.remove(this.group_key);
        }
      },
      setLastVisitedParentsToCache(parentIndexes: string) {

        if(parentIndexes) {
          LocalStorage.set(CONSTANTS.group_parent_indexes, parentIndexes);

          const parentRows = this.getParentRows(parentIndexes.split(','));
          const grouping_where = this.getGroupingWhere(parentRows);
          LocalStorage.set(CONSTANTS.group_parent_raw_where, JSON.stringify(grouping_where));
        }
      },
      resetAndFetchAgain() {
        this.groupingWhereMap.clear();
        this.getSavedFilters();
        this.loadData();
      },
      handleGroupChange() {
        this.setGroupsToCache();
        this.resetAndFetchAgain();
      },
      removeGroup (index: number) {
        this.groupedColumns.splice(index, 1);
        this.setGroupsToCache();
        this.resetAndFetchAgain();
      },
      async fetchGroupData (whereClause: any) {

        let response: any;
        try {
          // this.loading = true;
          if (whereClause.length > 0) {
            this.queryParams += '&raw_where=' + JSON.stringify(whereClause);
          }

          let groupItem = this.getGroupBy(whereClause.length);
          
          if (objLen(groupItem) !== 0) {
            const groups = []
            const group_item = {} as dynamicObj;
            group_item[groupItem.name] = groupItem.hasOwnProperty('group_by_type') ? groupItem.group_by_type : '';
            groups.push(group_item);
            this.queryParams += '&group_by=' + JSON.stringify(groups);
          }

          response = await documentListApiService.getListFromWarehouse(this.queryParams);
        } catch (err) {
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(msg);
          logError(err);
        } finally {
            // this.loading = false;
             
            return response;
        }

      },
      getGroupingWhere (parents: any) {

        let grouping_where = [] as dynamicObj[];

        for (let i = 0; i < parents.length; i++) {

          let field = parents[i].column_name;
          const where_item = { } as dynamicObj;

          if (this.date_fields.includes(field) ) {
            const foundItem = this.groupedColumns.find((column: any) => column.name === field);

            if(foundItem && foundItem.group_by_type) {
                where_item['operator'] = foundItem.group_by_type;
            } else {
                where_item['operator'] = 'month';
            }
          }

          where_item['field'] = field;
          where_item['value'] = parents[i][field];
          grouping_where.push(where_item);
        }

        return grouping_where;
      },

      getGroupBy(whereLength: number) : any {

        if(whereLength == this.groupedColumns.length) {
            return null;
        }

        return this.groupedColumns[whereLength];
      },
      // getGroupBy() : any {

      //   if(this.groupedColumns.length == 0) {
      //       return {};
      //   }

      //   return this.groupedColumns[0];
      // },
      async loadChildRowData(parentRowIndexes: string) {
        try {
          this.loading = true;
          
          const parentRows = this.getParentRows(parentRowIndexes.split(','));
          const groupingWhere = this.getGroupingWhere(parentRows);
          
          await this.applySavedFilters();
          let response = await this.fetchGroupData(groupingWhere);
          
          if (response.success === false) {
            throw response;
          }
          
          const data = this.prepareGroupingData(
            response.documents,
            this.getGroupBy(groupingWhere.length)?.name,
          );
          
          this.persistWhereClause(response.documents, groupingWhere, parentRowIndexes);
          this.applyCustomFormatOnRows(data);
          parentRows[parentRows.length - 1]['_children'] = data;
          this.loading = false;
        } catch(err) {
          this.loading = false;
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(msg);
          logError(err);
        }
        },
      persistWhereClause(data: any, groupingWhere: any, parentRowIndexes: string) {
        if(
          data &&
          data.length > 0 &&
          (
            data[0]._is_group_row === true ||
            Object.prototype.hasOwnProperty.call(data[0], 'count')
          )
        ) {
          return;
        }
        
        this.groupingWhereMap.set(parentRowIndexes, JSON.stringify(groupingWhere));
      },

    },
