export function parseDashboardQueryParams(
  queryParams: string,
): Record<string, string> {
  const params = new URLSearchParams(queryParams.replace(/^\?/, ''));
  const data = {} as Record<string, string>;

  params.forEach((value, key) => {
    if (key) {
      data[key] = value;
    }
  });

  return data;
}
