<!--vbase-->
<template>
  <template v-for="(row, rowIndex) in tableRows" :key="row['id']">
    <tr v-if="isGroupRow(row)" :data-index="rowIndex" data-test="document-group-row">
      <td class="table-body">
        <div
          class="display-flex"
          :style="'padding-left:' + getLeftPadding(false) + 'px'"
        >
          <q-checkbox dense :model-value="false" @click.stop data-test="document-group-checkbox" />
        </div>
      </td>
      <template v-for="(columnInfo, index) in table_columns" :key="index">
        <td class="table-body" :data-test="'document-group-cell-' + columnInfo.name">
          <template v-if="isGroupValueColumn(row, columnInfo.name, index)">
            <div
              class="display-flex items-center dashboard-group-row"
              @click="handleRowExpension(row, rowIndex)"
              data-test="document-group-expand"
            >
              <q-btn
                flat
                dense
                color="dark"
                @click.stop="handleRowExpension(row, rowIndex)"
                :icon="
                  row.is_expend ? 'keyboard_arrow_down' : 'keyboard_arrow_right'
                "
                class="q-mr-sm"
              />
              <span data-test="document-group-label">{{ row['label'] }} ({{ groupCount(row) }})</span>
            </div>
          </template>
        </td>
      </template>
    </tr>

    <tr v-else :class="setRowStyle(row)" :data-index="rowIndex" data-test="document-row" :data-document-id="row['id']">
      <!-- multi action -->
      <td class="table-body">
        <div
          class="display-flex"
          :style="'padding-left:' + getLeftPadding(true) + 'px'"
        >
          <q-checkbox
            dense
            v-model="row['rowSelection']"
            @update:model-value="checkRowExistance(row)"
            data-test="document-checkbox"
          />

          <!-- lock icon -->
          <template v-if="row['locked_by']">
            <q-icon
              name="lock"
              style="color: #7a7a7a"
              size="22px"
              class="mt-3 q-ml-sm"
              data-test="document-lock-icon"
            >
              <q-tooltip>{{ $t('doc_lock') }}</q-tooltip>
            </q-icon>
          </template>
        </div>
      </td>

      <!-- columns -->
      <template v-for="(columnInfo, index) in table_columns" :key="index">
        <td
          @click="
            columnInfo.name === 'status' && row['status'] === 'error'
              ? getErrorInfosWrapper(row)
              : rowClickWrapper(row)
          "
          :class="getClassesForColumn(row['status'], columnInfo.name)"
          class="text-weight-regular documnetCol table-body"
          :data-test="'document-cell-' + columnInfo.name"
        >
          <template v-if="columnInfo.name === 'pages'">
            <span
              class="q-ml-auto"
              style="display: flex; justify-content: right; padding-right: 16px"
              >{{ row[columnInfo.name] ? row[columnInfo.name] : '-' }}</span
            >
            <q-tooltip v-if="row[columnInfo.name]">{{
              row[columnInfo.name]
            }}</q-tooltip>
          </template>
          <template v-else-if="columnInfo.name === 'priority'">
            <span style="position: relative; left: 60px">{{
              row[columnInfo.name] ? row[columnInfo.name] : '-'
            }}</span>
            <q-tooltip v-if="row[columnInfo.name]">{{
              row[columnInfo.name]
            }}</q-tooltip>
          </template>
          <template v-else-if="columnInfo.name === 'status'">
            <q-badge align="middle" :class="getStatusClass(row['status'])">
              <span style="padding: 2px" class="dashboard-status-text">{{
                getLabelTranslation(row['status'])
              }}</span>
            </q-badge>
            <q-tooltip>
              {{ getLabelTranslation(row['status']) }}
            </q-tooltip>
            <q-tooltip v-if="row['status'] === 'error'">
              Click over status to see more details
            </q-tooltip>
          </template>
          <template v-else-if="columnInfo.name === 'doc_type'">
            {{ setDisplayDocType(row) }}
            <q-tooltip>
              {{ setDisplayDocType(row) }}
            </q-tooltip>
          </template>
          <template
            v-else-if="
              columnInfo.name === 'total_amount' ||
              columnInfo.name === 'total_net_amount' ||
              columnInfo.name === 'net_amount'
            "
          >
            <span class="q-ml-auto" style="padding-right: 16px">
              {{ row[columnInfo.name] }}
            </span>
            <q-tooltip v-if="row[columnInfo.name]">{{
              row[columnInfo.name]
            }}</q-tooltip>
          </template>
          <template
            v-else-if="dashboarDateColumns.indexOf(columnInfo.name) != -1"
          >
            {{ formatDateAccordingToPreference(row[columnInfo.name]) }}
            <q-tooltip v-if="row[columnInfo.name]">
              {{ formatDateAccordingToPreference(row[columnInfo.name]) }}
            </q-tooltip>
          </template>
          <!-- <template v-else-if="columnInfo.name == 'delivery_date' || columnInfo.name == 'invoice_date'">
                  {{ row[columnInfo.name] ? formatDateAccordingToPreference(row[columnInfo.name]) : '-' }}
                  <q-tooltip v-if="row[columnInfo.name]">
                    {{ formatDateAccordingToPreference(row[columnInfo.name]) }}
                  </q-tooltip>
                </template> -->

          <!-- <template v-else>
                {{ row[columnInfo.name] ? formatDateAccordingToPreference(row[columnInfo.name]) : '-' }}
                <q-tooltip v-if="row[columnInfo.name]">{{
                  row[columnInfo.name]
                }}</q-tooltip>
              </template> -->

          <template v-else>
            {{ row[columnInfo.name] ? row[columnInfo.name] : '-' }}
            <q-tooltip v-if="row[columnInfo.name]">{{
              row[columnInfo.name]
            }}</q-tooltip>
          </template>
        </td>
      </template>

      <!-- actions -->
      <td class="page-background">
        <!-- po match icon -->
        <template v-if="row.hasOwnProperty('po_match_status') && !isMediUser()">
          <template v-if="row.hasOwnProperty('po_match_icon')">
            <q-btn
              round
              flat
              size="10px"
              :class="
                row['po_match_icon'] == 'po_not_matched'
                  ? 'cursor-not-allowed'
                  : ''
              "
              style="pointer-events: unset !important"
              @click="
                (e) => {
                  e.stopPropagation();
                  viewPurchaseOrderWrapper(row);
                }
              "
            >
              <img
                :src="'/images/' + row['po_match_icon'] + '.svg'"
                width="20"
              />
              <q-tooltip>{{ $t(row['po_match_status']) }}</q-tooltip>
            </q-btn>
          </template>
          <q-btn
            v-else
            round
            flat
            size="10px"
            :ripple="false"
            style="cursor: default"
            class="invisible"
          >
          </q-btn>
        </template>

        <span class="q-px-sm">
          <Icon
            icon="mdi:file-check"
            width="20"
            height="20"
            class="vertical-middle"
            :class="renderquality(row) == '' ? 'invisible' : ''"
          />
          <q-tooltip v-if="row['quality']">
            <div class="row" v-html="renderquality(row)"></div>
          </q-tooltip>
        </span>

        <q-btn
          flat
          dense
          round
          @click.stop.prevent
          icon="more_horiz"
          class="dashboard-icon-btn"
        >
          <q-menu
            auto-close
            transition-show="jump-down"
            transition-hide="jump-up"
            anchor="bottom middle"
            self="top middle"
            class="dashboard-action-menu dashboard-light-text"
          >
            <q-list
              dense
              class="dashboard-light-text dashboard-menu-text"
              style="min-width: 100px"
            >
              <q-item
                clickable
                v-if="
                  row['status'] != 'finished' &&
                  row['status'] != 'workflow' &&
                  row['status'] != 'running' &&
                  row['status'] != 'restart_in_progress' &&
                  row['status'] != 'error' &&
                  row['status'] != 'pending_confirmation'
                "
                @click="rowClickWrapper(row)"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:pencil" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('validate')
                }}</q-item-section>
              </q-item>
              <q-item
                clickable
                @click="openAssignmentDlgWrapper(row['id'])"
                v-if="isDocReassignAble(row)"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:account-arrow-right" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('assign2')
                }}</q-item-section>
              </q-item>
              <q-item clickable @click="toFlowScreenWrapper(row.id)">
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:transit-connection-variant" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('flow_screen')
                }}</q-item-section>
              </q-item>
              <q-separator inset />
              <q-item
                clickable
                @click="downloadFile(row)"
                v-if="isDocDownloadable(row)"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:import" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('download')
                }}</q-item-section>
              </q-item>
              <q-item
                clickable
                @click="downloadZugferd(row)"
                v-if="isdownloadZugferd(row)"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:import" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('download_zugferd')
                }}</q-item-section>
              </q-item>
              <q-item
                clickable
                @click="downloadPeppol(row)"
                v-if="isdownloadPeppol(row)"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:import" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('download_peppol')
                }}</q-item-section>
              </q-item>
              <q-item
                clickable
                @click="downloadAnnotated(row)"
                v-if="isdownloadAnnotated(row)"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:import" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('download_annotated')
                }}</q-item-section>
              </q-item>
              <q-item
                clickable
                @click="downloadPreviewFile(row)"
                v-if="hasPreviewFile(row)"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:import" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('download_preview_files')
                }}</q-item-section>
              </q-item>
              <!-- <q-item clickable v-if="user_settings['WORKFLOW_BUILDER_MODULE_SETTING'] == true &&
                  (row['status'] == 'ready_for_validation' ||
                  row['status'] == 'ready_for_review' ||
                  row['status'] == 'pending_confirmation' ||
                  row['status'] == 'validated_pending_approval' ||
                  row['status'] == 'approved_pending_second_approval')
                  "
                  @click="triggerWorkflow(row['id'])">
                  <q-item-section avatar class="list-avatar">
                    <q-icon name="sitemap" size="xs" style="font-size: 14px"/>
                  </q-item-section>
                  <q-item-section class="dashboard-text">{{$t('trigger_workflow')}}</q-item-section>
                </q-item> -->
              <q-item
                clickable
                @click="goToExportWrapper(row['document_export_log'])"
                v-if="isExportAllowed(row['document_export_log'])"
              >
                <q-item-section avatar class="list-avatar">
                  <DashboardIcon
                    v-if="getExportIcon(row['document_export_log'])"
                    :src="getExportIcon(row['document_export_log'])"
                    :size="14"
                  />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('go_to_export')
                }}</q-item-section>
              </q-item>
              <q-item
                clickable
                v-if="isDocRestartable(row)"
                @click="restartExportWrapper(row['id'])"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:refresh" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('restart')
                }}</q-item-section>
              </q-item>
              <q-item
                clickable
                v-if="isExportErrorRestart(row)"
                @click="restartExportErrorWrapper(row['id'])"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon icon="mdi:refresh" width="14" height="14" />
                </q-item-section>
                <q-item-section class="dashboard-text">{{
                  $t('restart_export')
                }}</q-item-section>
              </q-item>
              <q-separator inset />
              <q-item
                clickable
                v-if="isDocDeleteable(row)"
                @click="readyForDeleteWrapper(row['id'])"
              >
                <q-item-section avatar class="list-avatar">
                  <Icon
                    icon="mdi:delete"
                    width="14"
                    height="14"
                    class="text-negative"
                  />
                </q-item-section>
                <q-item-section class="text-red-14">{{
                  $t('delete')
                }}</q-item-section>
              </q-item>
            </q-list>
          </q-menu>
        </q-btn>

        <q-icon
          v-if="row['restart_allowed'] == true"
          name="priority_high"
          class="headerError"
        >
          <q-tooltip>
            {{ $t('document_restart_alert') }}
          </q-tooltip>
        </q-icon>
      </td>
    </tr>

    <template v-if="row.is_expend && row._children">
      <component
        :is="componentName"
        :parentIndexes="getParentIndexes(rowIndex)"
        :table_columns="table_columns"
        :statusList="statusList"
        :restartExportedInvoices="restartExportedInvoices"
        @checkRowExistance="checkRowExistance"
        @rowClick="rowClick"
        @viewPurchaseOrder="viewPurchaseOrder"
        @openAssignmentDlg="openAssignmentDlg"
        @toFlowScreen="toFlowScreen"
        @downloadFile="downloadFile"
        @downloadZugferd="downloadZugferd"
        @downloadPeppol="downloadPeppol"
        @downloadAnnotated="downloadAnnotated"
        @downloadPreviewFile="downloadPreviewFile"
        @goToExport="goToExport"
        @restartExport="restartExport"
        @restartExportError="restartExportError"
        @readyForDelete="readyForDelete"
        @setErrorInfos="setErrorInfos"
        @loadChildRowData="loadChildRowData"
        @setLastVisitedParentsToCache="setLastVisitedParentsToCache"
      />
    </template>
  </template>
</template>

<script lang="ts">
import axios from 'axios';
import { storeToRefs } from 'pinia';
import { LocalStorage } from 'quasar';
import dateUtils from 'src/utils/date';
import { Acl } from 'src/core/acls/index';
import { defineComponent, ref } from 'vue';

import helperUtil from 'src/utils/helperUtil';
import docTypeLable from 'src/utils/docTypeLable';
import documentUtil from 'src/utils/documentUtil';
import { api, getAuthorizationToken } from 'pages/APIs';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
import {
  useUserStore,
  useDashboardStore,
  useSettingStore,
} from 'src/store/main';
import {
  readOnlyDocStatus,
  isInvoice,
  dashboarDateColumns,
} from 'src/constants';

export default defineComponent({
  name: 'TableBody',
  components: {
    
  },
  mixins: [documentUtil, docTypeLable, helperUtil, dateUtils],
  emits: [
    'checkRowExistance',
    'rowClick',
    'viewPurchaseOrder',
    'openAssignmentDlg',
    'toFlowScreen',
    'downloadFile',
    'downloadZugferd',
    'downloadPeppol',
    'downloadAnnotated',
    'downloadPreviewFile',
    'goToExport',
    'restartExport',
    'restartExportError',
    'readyForDelete',
    'setErrorInfos',
    'loadChildRowData',
    'setLastVisitedParentsToCache',
  ],
  props: {
    table_columns: {
      type: Array as any,
      default: () => [],
    },
    // row: {
    //   type: {} as any,
    //   default: {},
    // },
    statusList: {
      type: Array as any,
      default: () => [],
    },
    parentIndexes: {
      type: String,
      default: '',
    },
    restartExportedInvoices: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      dashboarDateColumns: dashboarDateColumns,
    };
  },
  watch: {
    display_data: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.prepareTableRows();
      },
    },
  },

  mounted() {
    this.prepareTableRows();
  },
  // this component is beaing include using recursion
  // TODO need to move methods in the utill as this componnet will render many time so this code is going to be duplicate in all of those components
  methods: {
    getStatusClass(status: string) {
      let status_class = '';
      const status_exists = this.statusList.hasOwnProperty(status);
      if (status_exists) {
        status_class = this.statusList[status]['class'];
      } else {
        status_class = 'bg-grey';
      }
      status_class += ' dashboard-status-badge';
      return status_class;
    },
    prepareTableRows() {
      if (!this.parentIndexes) {
        this.tableRows = this.display_data;
        return;
      }
      const parentRows = this.getParentRows(this.parentIndexes.split(','));
      this.tableRows = parentRows[parentRows.length - 1]._children;
    },
    setRowStyle(row: any) {
      if (
        row.hasOwnProperty('export_data_fetched') &&
        row['export_data_fetched'] === true
      ) {
        return 'exported-row';
      }
    },
    isGroupRow(row: any) {
      return (
        row?._is_group_row === true ||
        Object.prototype.hasOwnProperty.call(row, 'count')
      );
    },
    groupCount(row: any) {
      return row.count ??
        row.documents ??
        row.document_count ??
        row.documents_count ??
        0;
    },
    isGroupValueColumn(row: any, columnName: string, columnIndex: number) {
      if (row?.column_name === columnName) {
        return true;
      }

      const groupColumnIsVisible = this.table_columns.some(
        (column: any) => column.name === row?.column_name,
      );

      return columnIndex === 0 && !groupColumnIsVisible;
    },
    getLeftPadding(isLeafNode: boolean) {
      let padding = 0;
      if (!this.parentIndexes) {
        return padding;
      }
      padding = this.parentIndexes.split(',').length * 10;

      padding = padding + 10;
      if (isLeafNode) {
        padding = padding + 30;
      }

      return padding;
    },
    getErrorInfosWrapper(row: any) {
      // cache the parent Ids for refresh
      this.setLastVisitedParentsToCache(this.parentIndexes);
      this.getErrorInfos(row);
    },
    async getErrorInfos(row: any) {
      let ErrorInfos = false;
      let ErrorText = {};
      if (row['status'] !== 'error') {
        return;
      }
      let token: string = await getAuthorizationToken();

      const resp = await axios.get(addOrgIdQueryString(api.get_error_infos), {
        headers: {
          Authorization: token,
        },
        params: {
          doc_id: row['id'],
        },
      });
      resp['data']['row'] = row;
      // logInfo(resp['data']);
      if (Object.keys(resp).length === 1) {
        ErrorText = { message: 'None' };
      } else {
        ErrorText = resp['data'];
        ErrorInfos = true;
      }
      // set error details
      this.setErrorInfos(ErrorInfos, ErrorText);

      return ErrorInfos;
    },
    getClassesForColumn(status: string, column_name: string) {
      let styleClass = '';
      let styleClass2 = '';

      let styleClass1 =
        status === 'running' ? 'enableDrawingRectangle' : 'cursor-pointer';

      styleClass1 += column_name === 'filename' ? ' text-primary ' : '';
      styleClass1 += column_name.includes('amount') ? ' text-right ' : '';
      // if (column_name === 'status') {
      //   if (this.statusList.hasOwnProperty(status)) {
      //     styleClass2 = status ? this.statusList[status].class : '';
      //   }
      // }
      return (styleClass = styleClass1 + ' ' + styleClass2);
    },
    setDisplayDocType(row: any) {
      const type = this.getDocTypeForDisplay(row);
      const label = this.displayDocType(type);
      return String(label);
    },
    renderquality(row: any) {
      if (
        !this.user_settings['OCR_PERCENTAGE'] ||
        !this.user_settings['OCR_PERCENTAGE']
      ) {
        return;
      }

      let quality = '';
      if (row.hasOwnProperty('quality')) {
        let name = this.$t('overall');
        const item = row['quality'];
        if (
          parseInt(row['quality']) <
          parseInt(this.user_settings['OCR_PERCENTAGE'])
        ) {
          quality =
            name +
            ' : <FONT COLOR="#AA0500">' +
            row['quality'] +
            '</FONT COLOR>';
        }
        if (parseInt(item) == parseInt(this.user_settings['OCR_PERCENTAGE'])) {
          quality =
            name +
            ' : <FONT COLOR="#ffff00">' +
            row['quality'] +
            '</FONT COLOR>';
        }
        if (parseInt(item) > parseInt(this.user_settings['OCR_PERCENTAGE'])) {
          quality =
            name +
            ' : <FONT COLOR="#00ff00">' +
            row['quality'] +
            '</FONT COLOR>';
        }
      }
      return quality;
    },
    isDocReassignAble(row: any) {
      const status = String(row['status']);
      return (
        Acl.canUpdate(row) &&
        status != 'finished' &&
        status != 'workflow' &&
        status != 'running' &&
        status != 'restart_in_progress'
      );
    },
    isdownloadZugferd(row: any) {
      let is_visible = false;

      if (!this.isDocDownloadable(row)) {
        return is_visible;
      }

      if (
        readOnlyDocStatus.includes(row['status']) &&
        isInvoice(row['doc_type']) == true &&
        row['has_zugferd'] == true
      ) {
        is_visible = true;
      }

      return is_visible;
    },
    isdownloadPeppol(row: any) {
      let is_visible = false;
      if (!this.isDocDownloadable(row)) {
        return is_visible;
      }

      if (
        readOnlyDocStatus.includes(row['status']) &&
        isInvoice(row['doc_type']) == true &&
        row['has_peppol'] == true
      ) {
        is_visible = true;
      }

      return is_visible;
    },
    isdownloadAnnotated(row: any) {
      let is_visible = false;
      if (!this.isDocDownloadable(row)) {
        return is_visible;
      }

      if (row['has_annotated_version'] == true) {
        is_visible = true;
      }

      return is_visible;
    },
    isDocDownloadable(row: any) {
      const status = String(row['status']);
      return (
        Acl.canView(row) && status != 'running' && status != 'restart_in_progress'
      );
    },
    hasPreviewFile(row: any) {
      if (row.hasOwnProperty('preview_file_path') && row['preview_file_path']) {
        return true;
      }
      return false;
    },
    isExportAllowed(doc_export_log: any) {
      let export_log = this.getExportRecord(doc_export_log);
      if (!export_log || Object.keys(export_log).length === 0) {
        return false;
      }
      return true;
    },
    // duplicate is present in dashboard
    getExportRecord(doc_export_log: any) {
      if (!doc_export_log) {
        return {};
      }
      let login_source = LocalStorage.getItem('login_source') as string;
      if (!LocalStorage.has('login_source') || login_source === null) {
        return {};
      }
      login_source = login_source.toLowerCase();
      if (login_source == 'infor') {
        login_source = 'idm';
      }
      let export_log = {} as { [k: string]: any };
      for (const export_config of doc_export_log) {
        if (
          login_source === export_config.export_application.toLowerCase() &&
          export_config.document_url
        ) {
          export_log = export_config;
          break;
        }
      }
      return export_log;
    },
    getExportIcon(doc_export_log: any) {
      let export_log = this.getExportRecord(doc_export_log);
      if (!export_log || Object.keys(export_log).length === 0) {
        return;
      }
      let img = '';
      if (export_log.export_application == 'FLOW2') {
        img = 'images/flow2_icon.svg';
      }
      if (export_log.export_application == 'IDM') {
        img = 'images/idm_icon.svg';
      }
      if (export_log.export_application == 'ZUGFERD') {
        img = 'images/zugferd-icon.svg';
      }
      if (export_log.export_application == 'PEPPOL') {
        img = 'images/peppol-icon.svg';
      }
      return img;
    },
    // duplicate is present in dashboard
    isDocRestartable(row: any): boolean {
      if (!Acl.canUpdate(row)) {
        return false;
      }
      const status = String(row['status']);
      const restartAllowed = Boolean(row['restart_allowed']);

      if (this.restartExportedInvoices) {
        return true;
      } else {
        return (
          status === 'ready_for_validation' ||
          status === 'error' ||
          status === 'export_error' ||
          restartAllowed == true
        );
      }
    },
    // duplicate is present in dashboard
    isDocDeleteable(row: any) {
      const status = String(row['status']);
      return (
        Acl.canDeleteDoc(row) &&
        status != 'finished' &&
        status != 'workflow' &&
        status != 'running' &&
        status != 'restart_in_progress'
      );
    },
    isExportErrorRestart(row: any): boolean {
      if (!Acl.canUpdate(row)) {
        return false;
      }
      const status = String(row['status']);
      const restartAllowed = Boolean(row['restart_allowed']);

      if (this.restartExportedInvoices) {
        return true;
      } else {
        return status === 'export_error' || restartAllowed == true;
      }
    },
    handleRowExpension(row: any, rowIndex: number) {
      // means row is going to expend
      if (!row.is_expend) {
        // emit to load child data
        if (!row.hasOwnProperty('_children')) {
          const parentRowIndexes = this.getParentIndexes(rowIndex);
          this.loadChildRowData(parentRowIndexes);
        }
      }
      row.is_expend = !row.is_expend;
    },
    loadChildRowData(parentRowIndexes: string) {
      this.$emit('loadChildRowData', parentRowIndexes);
    },
    rowClickWrapper(row: any) {
      // cache the parent Ids for refresh
      this.setLastVisitedParentsToCache(this.parentIndexes);
      this.rowClick(row);
    },
    rowClick(row: any) {
      this.$emit('rowClick', row);
    },
    checkRowExistance(row: any) {
      this.$emit('checkRowExistance', row);
    },
    viewPurchaseOrderWrapper(row: any) {
      // cache the parent Ids for refresh
      this.setLastVisitedParentsToCache(this.parentIndexes);
      this.viewPurchaseOrder(row);
    },
    viewPurchaseOrder(row: any) {
      this.$emit('viewPurchaseOrder', row);
    },
    openAssignmentDlgWrapper(id: string) {
      // cache the parent Ids for refresh
      this.setLastVisitedParentsToCache(this.parentIndexes);
      this.openAssignmentDlg(id);
    },
    openAssignmentDlg(id: string) {
      this.$emit('openAssignmentDlg', id);
    },
    toFlowScreenWrapper(id: string) {
      // cache the parent Ids for refresh
      this.setLastVisitedParentsToCache(this.parentIndexes);
      this.toFlowScreen(id);
    },
    toFlowScreen(id: string) {
      this.$emit('toFlowScreen', id);
    },
    downloadFile(row: any) {
      this.$emit('downloadFile', row);
    },
    downloadZugferd(row: any) {
      this.$emit('downloadZugferd', row);
    },
    downloadPeppol(row: any) {
      this.$emit('downloadPeppol', row);
    },
    downloadAnnotated(row: any) {
      this.$emit('downloadAnnotated', row);
    },
    downloadPreviewFile(row: any) {
      this.$emit('downloadPreviewFile', row);
    },
    goToExportWrapper(doc_export_log: any) {
      // cache the parent Ids for refresh
      this.setLastVisitedParentsToCache(this.parentIndexes);
      this.goToExport(doc_export_log);
    },
    goToExport(doc_export_log: any) {
      this.$emit('goToExport', doc_export_log);
    },
    restartExportWrapper(id: string) {
      // cache the parent Ids for refresh
      this.setLastVisitedParentsToCache(this.parentIndexes);
      this.restartExport(id);
    },
    restartExport(id: string) {
      this.$emit('restartExport', id);
    },
    restartExportErrorWrapper(id: string) {
      // cache the parent Ids for refresh
      this.setLastVisitedParentsToCache(this.parentIndexes);
      this.restartExportError(id);
    },
    restartExportError(id: string) {
      this.$emit('restartExportError', id);
    },
    readyForDeleteWrapper(id: string) {
      // cache the parent Ids for refresh
      this.setLastVisitedParentsToCache(this.parentIndexes);
      this.readyForDelete(id);
    },
    readyForDelete(id: string) {
      this.$emit('readyForDelete', id);
    },
    setErrorInfos(ErrorInfos: boolean, ErrorText: any) {
      this.$emit('setErrorInfos', ErrorInfos, ErrorText);
    },
    getParentIndexes(index: number) {
      return this.parentIndexes
        ? this.parentIndexes + ',' + index
        : index.toString();
    },
    setLastVisitedParentsToCache(parentIndexes: string) {
      this.$emit('setLastVisitedParentsToCache', parentIndexes);
    },
  },
  setup() {
    const componentName = 'TableBody'; // Assign a dynamic name for the component

    const user_store = useUserStore();
    const { isMediUser } = user_store;

    const dashboard_store = useDashboardStore();
    const { display_data } = storeToRefs(dashboard_store);
    const { getParentRows } = dashboard_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    return {
      isMediUser,
      display_data,
      user_settings,
      tableRows: ref([] as any),

      getParentRows,

      componentName,
    };
  },
});
</script>
